#!/usr/bin/env python3
"""Patch the Android project generated by `flutter create` for DarkChess."""
from pathlib import Path
import re
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
app = root / "android" / "app"
manifest = app / "src" / "main" / "AndroidManifest.xml"

if not manifest.is_file():
    raise SystemExit(f"Android manifest not found: {manifest}. Run flutter create first.")

xml = manifest.read_text(encoding="utf-8")
if "android.permission.INTERNET" not in xml:
    xml = re.sub(
        r"(<manifest\b[^>]*>)",
        r'\1\n    <uses-permission android:name="android.permission.INTERNET"/>',
        xml,
        count=1,
    )
xml = re.sub(r'android:label="[^"]*"', 'android:label="DarkChess"', xml, count=1)
manifest.write_text(xml, encoding="utf-8")

kts = app / "build.gradle.kts"
groovy = app / "build.gradle"
gradle = kts if kts.is_file() else groovy
if not gradle.is_file():
    raise SystemExit("No android/app/build.gradle.kts or build.gradle found.")

g = gradle.read_text(encoding="utf-8")
if "keystorePropertiesFile" not in g:
    if gradle == kts:
        header = '''import java.util.Properties
import java.io.FileInputStream

val keystoreProperties = Properties()
val keystorePropertiesFile = rootProject.file("key.properties")
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(FileInputStream(keystorePropertiesFile))
}

'''
        signing = '''    signingConfigs {
        create("release") {
            if (keystorePropertiesFile.exists()) {
                keyAlias = keystoreProperties["keyAlias"] as String
                keyPassword = keystoreProperties["keyPassword"] as String
                storeFile = file(keystoreProperties["storeFile"] as String)
                storePassword = keystoreProperties["storePassword"] as String
            }
        }
    }
    buildTypes {'''
        g = header + g.replace("    buildTypes {", signing, 1)
        g = re.sub(
            r'signingConfig\s*=\s*signingConfigs\.getByName\("debug"\)',
            'signingConfig = if (keystorePropertiesFile.exists()) signingConfigs.getByName("release") else signingConfigs.getByName("debug")',
            g,
        )
    else:
        header = '''import java.util.Properties
import java.io.FileInputStream

def keystoreProperties = new Properties()
def keystorePropertiesFile = rootProject.file('key.properties')
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}

'''
        signing = '''    signingConfigs {
        release {
            if (keystorePropertiesFile.exists()) {
                keyAlias keystoreProperties['keyAlias']
                keyPassword keystoreProperties['keyPassword']
                storeFile file(keystoreProperties['storeFile'])
                storePassword keystoreProperties['storePassword']
            }
        }
    }
    buildTypes {'''
        g = header + g.replace("    buildTypes {", signing, 1)
        g = re.sub(
            r'signingConfig\s+signingConfigs\.debug',
            'signingConfig keystorePropertiesFile.exists() ? signingConfigs.release : signingConfigs.debug',
            g,
        )

if gradle == kts:
    g = re.sub(r'minSdk\s*=\s*flutter\.minSdkVersion', 'minSdk = 24', g)
else:
    g = re.sub(r'minSdkVersion\s+flutter\.minSdkVersion', 'minSdkVersion 24', g)

gradle.write_text(g, encoding="utf-8")

# AGP 9 compatibility: keep the legacy DSL available for Flutter plugins
# that have not migrated yet (including the Stockfish Android plugin).
# Write one real property per line; do not leave escaped "\\n" text in this file.
gradle_properties = root / "android" / "gradle.properties"
if gradle_properties.is_file():
    props = gradle_properties.read_text(encoding="utf-8")
    lines = [
        line for line in props.splitlines()
        if not line.strip().startswith("android.newDsl=")
        and not line.strip().startswith("android.builtInKotlin=")
    ]
    lines.extend(["android.newDsl=false", "android.builtInKotlin=false"])
    gradle_properties.write_text("\\n".join(lines) + "\\n", encoding="utf-8")

print("Android manifest and Gradle configuration patched.")
